from pathlib import Path
import base64
import xml.etree.ElementTree as ET
root=Path('app/src/main')
res=root/'res'
work=root/'java/jp/wakeguard/alarm'
def write(name,s):
    p=work/name
    p.write_text(s,encoding='utf-8')
def replace(name,old,new):
    p=work/name
    s=p.read_text(encoding='utf-8')
    if old not in s: raise RuntimeError(f'{name}: pattern missing: {old[:90]!r}')
    p.write_text(s.replace(old,new),encoding='utf-8')
assets=res/'drawable-nodpi';assets.mkdir(parents=True,exist_ok=True)
(assets/'ic_ignido_v295_foreground.png').write_bytes(base64.b64decode(''))
for folder in ('mipmap-anydpi-v26','mipmap-anydpi-v33'):
    for name in ('ic_launcher.xml','ic_launcher_round.xml'):
        p=res/folder/name
        s=p.read_text(encoding='utf-8')
        assert 'ic_ignido_v294_fg' in s
        s=s.replace('@drawable/ic_ignido_v294_fg','@drawable/ic_ignido_v295_foreground')
        p.write_text(s,encoding='utf-8')
        ET.parse(p)
